from dsl import *

PREG = "General pregnancy information, not medical advice. Always follow your midwife or doctor. Seek urgent care for bleeding, severe pain, severe headache or vision changes, fever, fluid loss or reduced baby movements."
BIRTH = "Antenatal education, not medical advice. Your midwife or doctor's guidance overrides anything here; call your maternity unit if you are unsure whether to go in."
POST = "General postnatal information, not medical advice. Contact your midwife, GP or emergency services for heavy bleeding, fever, chest pain, calf pain, severe headache, or any thoughts of harming yourself or your baby."
LACT = "General lactation information, not medical advice. Confirm medications with a pharmacist or the LactMed / BfN databases, and see a clinician or IBCLC for persistent pain, fever, or feeding and weight concerns."
MENO = "General menopause information, not medical advice. HRT and other prescribing decisions belong with your doctor; report bleeding after 12 months without periods, very heavy bleeding, or chest pain promptly."
STRONG = "Fitness and nutrition information, not medical advice. Get clearance from your doctor before a new programme if you have osteoporosis, heart disease, prolapse or a recent injury; stop and seek help for chest pain, dizziness or sharp pain."
FAM = "Educational information about fertility awareness, not medical or contraceptive advice. Charting to avoid pregnancy requires proper instruction and consistent daily records; unclear signs mean treat the day as fertile."
TTC = "General fertility information, not medical advice. Do not start or stop medications without your doctor; see a GP or fertility specialist for personal assessment and testing."
IVF = "General information to support your treatment, not medical advice. Your clinic's written protocol and instructions always take precedence; call your clinic for any concern and emergency services for severe symptoms."
PELVIC = "General pelvic health information, not medical advice or a substitute for assessment by a pelvic health physiotherapist or doctor. Seek care for pain, bleeding, blood in urine, or sudden changes."

